     1→import { useState } from "react";
     2→import { Button } from "@/components/ui/button";
     3→import { Badge } from "@/components/ui/badge";
     4→import { Checkbox } from "@/components/ui/checkbox";
     5→import { TableCell, TableRow } from "@/components/ui/table";
     6→import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
     7→import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
     8→import {
     9→  ChevronDown, ChevronUp, Phone, Mail, MapPin,
    10→  FileText, Archive
    11→} from "lucide-react";
    12→import { toast } from "sonner";
    13→import type { Result } from "@/pages/Index";
    14→import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";
    15→
    16→// Sub-components
    17→import CandidateSummary from "@/components/candidate/CandidateSummary";
    18→import SkillsDetailPanel from "@/components/candidate/SkillsDetailPanel";
    19→import ExperiencePanel from "@/components/candidate/ExperiencePanel";
    20→import EducationPanel from "@/components/candidate/EducationPanel";
    21→import JDAlignedPanel from "@/components/candidate/JDAlignedPanel";
    22→import StrengthsGapsPanel from "@/components/candidate/StrengthsGapsPanel";
    23→import AINudgePanel from "@/components/candidate/AINudgePanel";
    24→import InterviewQuestionsPanel from "@/components/candidate/InterviewQuestionsPanel";
    25→import StageTracker from "@/components/candidate/StageTracker";
    26→import type { HiringStage } from "@/hooks/useStageTracker";
    27→
    28→interface CandidateRowProps {
    29→  result: Result;
    30→  index: number;
    31→  isExpanded: boolean;
    32→  isSelected: boolean;
    33→  jobTitle?: string | null;
    34→  onToggleRow: (id: string) => void;
    35→  onToggleSelect: (resumeId: string) => void;
    36→  onDownload: (filePath: string, filename: string) => void;
    37→  onDelete: (resumeId: string, filePath: string | null) => void;
    38→  onDismiss: (resumeId: string) => void;
    39→  formatCandidateName: (filename: string) => string;
    40→  currentStage?: HiringStage | null;
    41→  stageUpdatedAt?: string | null;
    42→  onStageChange?: (resumeId: string, stage: HiringStage) => void;
    43→  onRewriteJd?: () => void;
    44→}
    45→
    46→const getScoreColor = (score: number) => {
    47→  if (score >= 70) return "bg-score-skills";
    48→  if (score >= 40) return "bg-warning";
    49→  return "bg-destructive";
    50→};
    51→
    52→const getScoreTextColor = (score: number) => {
    53→  if (score >= 70) return "text-score-skills";
    54→  if (score >= 40) return "text-warning";
    55→  return "text-destructive";
    56→};
    57→
    58→const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
    59→  if (score >= 70) return { label: "Strong", variant: "success" };
    60→  if (score >= 40) return { label: "Good", variant: "warning" };
    61→  return { label: "Weak", variant: "destructive" };
    62→};
    63→
    64→const getRankDisplay = (index: number) => {
    65→  if (index < 3) {
    66→    const colors = [
    67→      "bg-score-overall text-white",
    68→      "bg-muted-foreground/60 text-white",
    69→      "bg-warning text-white",
    70→    ];
    71→    return (
    72→      <span className={`inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-bold ${colors[index]}`}>
    73→        {index + 1}
    74→      </span>
    75→    );
    76→  }
    77→  return (
    78→    <span className="inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-medium bg-muted text-muted-foreground">
    79→      {index + 1}
    80→    </span>
    81→  );
    82→};
    83→
    84→const CandidateRow = ({
    85→  result: r,
    86→  index,
    87→  isExpanded,
    88→  isSelected,
    89→  jobTitle,
    90→  onToggleRow,
    91→  onToggleSelect,
    92→  onDownload,
    93→  onDelete,
    94→  onDismiss,
    95→  formatCandidateName,
    96→  currentStage,
    97→  stageUpdatedAt,
    98→  onStageChange,
    99→  onRewriteJd,
   100→}: CandidateRowProps) => {
   101→  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
   102→  const strength = !r.pending ? getStrengthLabel(r.overall_score) : null;
   103→
   104→  return (
   105→    <>
   106→    <Collapsible open={isExpanded} onOpenChange={() => onToggleRow(r.id)} asChild>
   107→      <>
   108→        {/* Collapsed Row */}
   109→        <TableRow className="cursor-pointer hover:bg-muted/50 transition-colors" onClick={() => !r.pending && onToggleRow(r.id)}>
   110→          <TableCell onClick={(e) => e.stopPropagation()}>
   111→            <Checkbox checked={isSelected} onCheckedChange={() => onToggleSelect(r.resume_id)} />
   112→          </TableCell>
   113→          <TableCell className="text-center">
   114→            {r.pending ? <span className="text-sm text-muted-foreground">—</span> : getRankDisplay(index)}
   115→          </TableCell>
   116→          <TableCell className="font-medium">
   117→            <div className="flex flex-col">
   118→              <span className="text-sm">{r.candidate_name || formatCandidateName(r.filename)}</span>
   119→              {r.candidate_location && (
   120→                <span className="flex items-center gap-1 text-xs text-muted-foreground mt-0.5">
   121→                  <MapPin className="h-3 w-3" /> {r.candidate_location}
   122→                </span>
   123→              )}
   124→            </div>
   125→          </TableCell>
   126→          <TableCell>
   127→            {r.pending ? (
   128→              <Badge variant="outline" className="text-xs">Pending</Badge>
   129→            ) : (
   130→              <div className="flex items-center gap-2">
   131→                <div className="flex-1 h-2 rounded-full bg-secondary overflow-hidden max-w-[100px]">
   132→                  <div
   133→                    className={`h-full rounded-full transition-all ${getScoreColor(r.overall_score)}`}
   134→                    style={{ width: `${Math.min(r.overall_score, 100)}%` }}
   135→                  />
   136→                </div>
   137→                <span className={`text-sm font-semibold tabular-nums min-w-[3ch] ${getScoreTextColor(r.overall_score)}`}>
   138→                  {r.overall_score?.toFixed(0)}%
   139→                </span>
   140→              </div>
   141→            )}
   142→          </TableCell>
   143→          <TableCell>
   144→            <div className="flex flex-wrap items-center gap-1">
   145→              {!r.pending && strength && (
   146→                <Badge variant={strength.variant} className="text-[10px]">
   147→                  {strength.label}
   148→                </Badge>
   149→              )}
   150→              {!r.pending && currentStage && currentStage !== "applied" && (
   151→                <Badge variant="outline" className="text-[10px] capitalize">
   152→                  {currentStage}
   153→                </Badge>
   154→              )}
   155→              {!r.pending && r.scoring_version === "heuristic" && (
   156→                <TooltipProvider delayDuration={300}>
   157→                  <Tooltip>
   158→                    <TooltipTrigger asChild>
   159→                      <span className="inline-flex items-center text-[10px] px-1.5 py-0.5 rounded bg-muted text-muted-foreground font-medium cursor-default">
   160→                        Quick
   161→                      </span>
   162→                    </TooltipTrigger>
   163→                    <TooltipContent className="max-w-xs text-xs">
   164→                      This candidate was ranked by keyword matching. Top 20 candidates receive full AI scoring.
   165→                    </TooltipContent>
   166→                  </Tooltip>
   167→                </TooltipProvider>
   168→              )}
   169→            </div>
   170→          </TableCell>
   171→          <TableCell>
   172→            <div className="flex items-center gap-0.5" onClick={(e) => e.stopPropagation()}>
   173→              <TooltipProvider delayDuration={300}>
   174→                {/* Phone */}
   175→                <Tooltip>
   176→                  <TooltipTrigger asChild>
   177→                    {r.candidate_phone ? (
   178→                      <a
   179→                        href={`tel:${r.candidate_phone}`}
   180→                        onClick={(e) => {
   181→                          if (!/Mobi|Android/i.test(navigator.userAgent)) {
   182→                            e.preventDefault();
   183→                            navigator.clipboard.writeText(r.candidate_phone!);
   184→                            toast.success("Phone number copied!");
   185→                          }
   186→                        }}
   187→                      >
   188→                        <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary">
   189→                          <Phone className="h-3.5 w-3.5" />
   190→                        </Button>
   191→                      </a>
   192→                    ) : (
   193→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
   194→                        <Phone className="h-3.5 w-3.5" />
   195→                      </Button>
   196→                    )}
   197→                  </TooltipTrigger>
   198→                  <TooltipContent>{r.candidate_phone ? (/Mobi|Android/i.test(navigator.userAgent) ? r.candidate_phone : "Copy phone") : "No phone"}</TooltipContent>
   199→                </Tooltip>
   200→
   201→                {/* Email */}
   202→                <Tooltip>
   203→                  <TooltipTrigger asChild>
   204→                    {r.candidate_email ? (
   205→                      <Button
   206→                        variant="ghost"
   207→                        size="icon"
   208→                        className="h-7 w-7 text-muted-foreground hover:text-primary"
   209→                        onClick={() => setEmailDialogOpen(true)}
   210→                      >
   211→                        <Mail className="h-3.5 w-3.5" />
   212→                      </Button>
   213→                    ) : (
   214→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
   215→                        <Mail className="h-3.5 w-3.5" />
   216→                      </Button>
   217→                    )}
   218→                  </TooltipTrigger>
   219→                  <TooltipContent>{r.candidate_email || "No email"}</TooltipContent>
   220→                </Tooltip>
   221→
   222→                {/* Download */}
   223→                <Tooltip>
   224→                  <TooltipTrigger asChild>
   225→                    {r.file_path ? (
   226→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary" onClick={() => onDownload(r.file_path!, r.filename)}>
   227→                        <FileText className="h-3.5 w-3.5" />
   228→                      </Button>
   229→                    ) : (
   230→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
   231→                        <FileText className="h-3.5 w-3.5" />
   232→                      </Button>
   233→                    )}
   234→                  </TooltipTrigger>
   235→                  <TooltipContent>{r.file_path ? "Download resume" : "No file"}</TooltipContent>
   236→                </Tooltip>
   237→
   238→                {/* Archive */}
   239→                <Tooltip>
   240→                  <TooltipTrigger asChild>
   241→                    <Button
   242→                      variant="ghost" size="icon"
   243→                      className="h-7 w-7 text-muted-foreground hover:text-amber-500"
   244→                      onClick={() => onDismiss(r.resume_id)}
   245→                    >
   246→                      <Archive className="h-3.5 w-3.5" />
   247→                    </Button>
   248→                  </TooltipTrigger>
   249→                  <TooltipContent>Archive candidate</TooltipContent>
   250→                </Tooltip>
   251→              </TooltipProvider>
   252→
   253→              {!r.pending && (
   254→                <CollapsibleTrigger asChild>
   255→                  <Button variant="ghost" size="icon" className="h-7 w-7">
   256→                    {isExpanded ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
   257→                  </Button>
   258→                </CollapsibleTrigger>
   259→              )}
   260→            </div>
   261→          </TableCell>
   262→        </TableRow>
   263→
   264→        {/* Expanded Detail — New Layout */}
   265→        {!r.pending && (
   266→          <CollapsibleContent asChild>
   267→            <TableRow className="bg-muted/30 hover:bg-muted/30">
   268→              <TableCell colSpan={6} className="p-5">
   269→                <div className="space-y-4">
   270→                  {/* 1. AI Summary */}
